 Ext._define('rh.gfp.conference.massmanagementfunds.Grid', {
    extend: 'core.RestfulGrid',

    rest: 'rh.gfp.conference.massmanagementfunds.Restful',

    hideItemsToolbar: ['edit',],
    hideActions: ['remove', 'copy', 'edit'],

    configOrderToolBar: ['payroll', '-','search', 'delete'],

    getColumnModel: function(){
        if(!this._columnModel)
            this._columnModel = Ext._create(
                'Ext.grid.ColumnModel',
                [
                    {header: 'Chave', dataIndex: 'pk', width: 55, hidden: true},
                    {header: 'Número', dataIndex: 'numero_display', width: 60},
                    {header: 'Título', dataIndex: 'titulo', 'minWidth': 240, id: 'autoExpandColumn'},
                    {header: 'Automático', dataIndex: 'automatico', width: 30, hidden: true},
                ]
            );

        return this._columnModel;
    },

    observePayroll: function(){
        if(this.payroll()){
            this.setParam('folha', this.payroll().pk);
            this.setFilterProperty('folha', this.payroll().pk, 100);
        }
        else{
            this.getStore().removeAll();
            this.setFilterProperty('folha', 0, 100, false);
        }
    },

    payroll: function(value, dispatch){
        dispatch = core.nullValue(dispatch, true);

        if(value !== undefined){
            this._payroll = value;

            if(dispatch) this.observePayroll();
        }
        else
            return this._payroll;
    },

    getCurrentPayroll: function(){
        Ext.Ajax.request({
            url: toolkit.util.Normalize.controller_action(
                'GFPPayroll',
                'working'
            ),
            method: 'GET',
            success: function(request) {
                var code = Ext.decode(request.responseText);
                if(code.payroll && code.payroll.id){
                    var payrollField = this.getPayrollField();
                    if(payrollField)
                        payrollField.setValue(code.payroll.id);
                }
            },
            scope: this
        });
    },

    getPayrollField: function(cfg) {
        if(!this._payrollField)
            this._payrollField = Ext._create('core.fields.AutocompleteField', {
                fieldLabel: 'Folha',
                name: 'payroll',
                rest: 'rh.gfp.payroll.PayrollRestful',
                width: 300,
                comboListeners: {
                    scope: this,
                    changevalid: function(combo, value, oldvalue, valid) {
                        if(valid)
                            this.payroll(combo.store.getById(value).data, true);
                    }
                }
            });

        return this._payrollField;
    },

    getToolbar: function (cfg) {
        if (!this._toolbar) {
            cfg = core.nullValue(cfg, {});
            Ext.apply(cfg, { gridAutoLoad: false, });
        
            this._toolbar = rh.gfp.conference.massmanagementfunds.Grid.superclass.getToolbar.call(this, cfg);
            this._toolbar.insert(5,
                {
                text: 'Deletar lançamentos',
                iconCls: true,
                icon: "/" + global.Context + "/static/engine/images/icons/athenas-0246.png",
                handler: function () {
                    var selected = this.getSelectionModel().getSelected();
                    if (!selected) {
                        Ext.Msg.show({
                            title: "Deletar lançamentos",
                            width: 350,
                            icon: Ext.Msg.ERROR,
                            buttons: Ext.Msg.OK,
                            msg: "Selecione um item",
                        });
                    } else {
                        event_pk = this.getSelectionModel().getSelected().id
                        payroll_pk = this._payroll.id
                        if (this.ownerCt && this.ownerCt._event && this.ownerCt._event.automatico) {
                            Ext.Msg.show({
                                title: 'Exclusão de verbas automáticas',
                                msg: 'Não é permitido a exclusão de verbas automáticas, verificar o cadastro da verba!',
                                icon: Ext.Msg.INFO,
                                buttons:  Ext.Msg.OK,
                            })
                        } else {
                            Ext.Msg.show({
                                msg: 'Tem certeza que deseja deletar os lançamentos da verba: ' + this.getSelectionModel().getSelected().json.unicode + '?',
                                icon: Ext.Msg.QUESTION,
                                buttons: Ext.Msg.YESNO,
                                scope: this,
                                fn: function (b) {
                                    if (b == 'no') return;
                    
                                    Ext.Ajax.request({
                                        url: toolkit.util.Normalize.controller_action('GFPMassManagementFunds','delete_entries'),
                                        params: {
                                            event_pk: event_pk,
                                            payroll_pk: payroll_pk,
                                        },
                                        success: function(request) {
                                            var obj = Ext.decode(request.responseText);
                                            Ext.Msg.show({
                                                width:"400px",
                                                title: this.title,
                                                icon: Ext.Msg.INFO,
                                                buttons: Ext.Msg.OK,
                                                msg: obj.message
                                            });
                                            this.getStore().reload();
                                        },
                                        failure: function() {
                                            Ext.Msg.show({
                                                title: this.title,
                                                icon: Ext.Msg.ERROR,
                                                buttons: Ext.Msg.OK,
                                                msg: 'Recurso indisponivel no momento, tente novamente mais tarde.'
                                            });
                                        },
                                        scope: this
                                    });
                                }
                            })
                        }
                    }            
                },
                scope: this
                }
            );
        }
        return this._toolbar;
      },

    getConfigActionsItems: function(cfg){
        if(!this._configActionsItems){
            rh.gfp.conference.massmanagementfunds.Grid.superclass.getConfigActionsItems.call(this, cfg);
            var _menu = {
                payroll: this.getPayrollField(cfg),
            };
            Ext.apply(this._configActionsItems, _menu);

        }
        return this._configActionsItems;
    },

    postCreate: function(grid){
        this.getCurrentPayroll();
    },

});

core.RestfulGrid.register(
    'rh.gfp.conference.massmanagementfunds.Restful',
    'rh.gfp.conference.massmanagementfunds.Grid'
);
